const state = items[0]?.json?.state || items[0]?.json || {};
const now = new Date().toISOString();
const company = state.inputs?.company_name || state.entity?.legal_name || '';
const industry = state.inputs?.industry || '';
const overridePeers = state.inputs?.advanced_context?.known_competitors || state.inputs?.advanced_context?.peers || [];
state.research = state.research || {};
state.research.private_research = {
  source_status: {
    sec_edgar: 'NO_PUBLIC_CIK_OR_NOT_PUBLIC',
    serper: 'OPTIONAL_DISCOVERY_HELPER',
    company_website: 'PUBLIC_SOURCE_PRIORITY',
    company_ir_or_newsroom: 'PUBLIC_SOURCE_PRIORITY',
    founder_source_urls: Object.keys(state.inputs?.advanced_context || {}).length ? 'AVAILABLE' : 'EMPTY',
    apify_linkedin: 'DISABLED_NO_PAID_APIS',
    apify_crunchbase: 'DISABLED_NO_PAID_APIS'
  },
  serper_jobs: [
    { job_id: 'private_revenue_signal', query: `${company} annual revenue investor relations`, purpose: 'Find revenue disclosures, press mentions, or reliable estimates.', reliability_floor: 'LOW' },
    { job_id: 'funding_valuation_signal', query: `${company} funding valuation Crunchbase PitchBook`, purpose: 'Find funding rounds, valuation signals, and investor disclosures.', reliability_floor: 'LOW' },
    { job_id: 'headcount_growth_signal', query: `${company} LinkedIn employees headcount growth`, purpose: 'Find headcount scale and growth signals.', reliability_floor: 'LOW' },
    { job_id: 'customer_product_signal', query: `${company} customers revenue press release ${industry}`, purpose: 'Find customer count, product traction, partnerships, or demand signals.', reliability_floor: 'LOW' },
    { job_id: 'risk_event_signal', query: `${company} layoffs restructuring acquisition lawsuit leadership`, purpose: 'Find operational, legal, and leadership events.', reliability_floor: 'LOW' }
  ],
  public_page_jobs: [
    { job_id: 'company_homepage_about', source_type: 'public_company_site', query_hint: `${company} about employees revenue customers`, output_fields: ['employee_count_if_stated', 'customer_count_if_stated', 'locations', 'business_description'], reliability_floor: 'LOW' },
    { job_id: 'company_newsroom_press', source_type: 'public_company_site_or_newsroom', query_hint: `${company} press release funding revenue customers partnership`, output_fields: ['funding_if_publicly_stated', 'revenue_if_publicly_stated', 'customer_or_product_signals'], reliability_floor: 'LOW' },
    { job_id: 'founder_provided_urls', source_type: 'manual_public_urls', query_hint: 'Use advanced_context.source_urls when provided.', output_fields: ['explicitly_cited_numbers_only'], reliability_floor: 'MEDIUM_IF_DIRECT_SOURCE' }
  ],
  peer_jobs: {
    founder_override_peers: Array.isArray(overridePeers) ? overridePeers : [],
    selection_rule: 'Use founder override peers first. If empty, choose 4-6 public peers by business model, customer segment, geography, and revenue model.',
    metrics_rule: 'Only compute peer EV/Revenue or EV/EBITDA ranges if source data exists and the private-company denominator is source-labeled.'
  },
  estimate_policy: {
    revenue: 'May be included only when source directly states revenue or enough explicit source-backed data supports a range. Otherwise N/A.',
    valuation: 'Use funding valuation only when directly sourced; never infer from hype/news language.',
    market_cap: 'Always N/A for private companies. Optional EV range only if clearly labeled as estimate.',
    reliability: 'Private-company quantitative estimates are LOW or VERY_LOW by default. Never render as authoritative.'
  },
  normalized_output_requirements: [
    'Every private company number must include source_name, source_url, source_date, confidence, and is_estimate=true.',
    'Do not use paid private-company databases or paid scraping actors in the core path.',
    'Unsupported estimates must become N/A with reason.',
    'Claude agents must receive estimate labels visibly in the normalized bundle.'
  ]
};
state.audit_log = state.audit_log || [];
state.audit_log.push({ timestamp: now, workflow_name: 'WF_RESEARCH_PRIVATE', status: 'READY', message: 'Private-company research jobs and reliability gates prepared. External fetches require Serper/Apify credentials.' });
return [{ json: state }];

const state = $('Build Private Research Bundle').first().json;
const serper = $('Serper Private Signal Search').first().json || {};
const now = new Date().toISOString();
const organic = serper.organic || [];
state.research.private_research.serper_results = organic.slice(0, 10).map((item) => ({
  title: item.title || '',
  snippet: item.snippet || '',
  source_url: item.link || '',
  source_name: 'Serper Google Search',
  source_date: now,
  confidence: item.link ? 'LOW' : 'VERY_LOW',
  is_estimate: true
}));
state.research.private_research.source_status.serper = organic.length ? 'OK' : 'EMPTY_OR_FAILED';
state.audit_log = state.audit_log || [];
state.audit_log.push({ timestamp: now, workflow_name: 'WF_RESEARCH_PRIVATE', status: organic.length ? 'OK' : 'WARN', message: `Attached ${organic.length} private-company Serper signal results.` });
return [{ json: state }];

